INSERT INTO `terms_template_versions` VALUES
('24c10067-f44e-5199-8ff2-be0aa1c0a330','7b51c4ef-1984-5a2e-a83e-a900c3d0b67a',1,'<ol><li>This is a budgetary estimate prepared at concept stage; variance of +/-10% expected.</li><li>Design fee and PMC fee shown separately.</li><li>Final BOQ will be issued after GFC drawings.</li></ol>','Initial version','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-04-03 10:00:00'),
('8195253a-de13-5958-b2c7-01c04e2203ee','e2ec5efa-3bee-54fd-93ba-6e8eaf3cfd9f',1,'<ol><li>Quantities are indicative and will be measured at site on completion.</li><li>Brands as per approved material schedule; equivalent alternatives only with written approval.</li><li>Loose furniture, soft furnishings and appliances excluded unless listed.</li><li>Miscellaneous provision @10% covers minor consumables and site contingencies.</li></ol>','Initial version','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-04-03 10:00:00'),
('965a5c5b-e3f0-5f14-877b-b94df7bd0289','9ac836d7-a2a4-500b-98bf-dc2c619c4c65',1,'<ol><li>All rates are exclusive of GST @18% unless mentioned.</li><li>Quotation valid for 30 days from date of issue.</li><li>Any work beyond approved scope will be treated as an extra item and billed at agreed rates.</li><li>Client to provide water and electricity at site free of cost.</li><li>Disputes subject to Delhi jurisdiction only.</li></ol>','Initial version','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-04-03 10:00:00'),
('c3041166-a741-5fad-a495-de7b15c02841','e2ec5efa-3bee-54fd-93ba-6e8eaf3cfd9f',2,'<ol><li>Quantities are indicative and will be measured at site on completion.</li><li>Brands as per approved material schedule; equivalent alternatives only with written approval.</li><li>Loose furniture, soft furnishings and appliances excluded unless listed.</li><li>Miscellaneous provision @10% covers minor consumables and site contingencies.</li></ol>','Updated GST and validity clauses','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-08-21 10:00:00'),
('dab0e269-80f5-5dc3-a17b-03935dddde72','06fbe897-b020-5b1a-a191-f3eb19035a2e',1,'<ol><li>Design fee payable in stages: 10% token, 30% on concept approval, 30% on GFC drawings, 30% during execution.</li><li>Two rounds of revisions included per design stage.</li><li>Site visits: weekly during execution.</li></ol>','Initial version','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-04-03 10:00:00'),
('eed97cd8-08ba-58b7-ac54-1259c4c5fa7a','1a4acd77-5dae-590a-853b-3d39b3a7e51d',1,'<ol><li>Timelines assume timely approvals (within 5 working days) and payments as per schedule.</li><li>Society/RWA restrictions on working hours may extend durations.</li><li>Monsoon (Jul-Aug) may affect civil and external works.</li></ol>','Initial version','c4af5469-bbd1-11f1-9c80-02fc00000001','2026-04-03 10:00:00'),
('fb48497e-7044-5b2b-be2f-42802e18d5fa','9ac836d7-a2a4-500b-98bf-dc2c619c4c65',2,'<ol><li>All rates are exclusive of GST @18% unless mentioned.</li><li>Quotation valid for 30 days from date of issue.</li><li>Any work beyond approved scope will be treated as an extra item and billed at agreed rates.</li><li>Client to provide water and electricity at site free of cost.</li><li>Disputes subject to Delhi jurisdiction only.</li></ol>','Updated GST and validity clauses','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-08-21 10:00:00');
INSERT INTO `terms_templates` VALUES
('06fbe897-b020-5b1a-a191-f3eb19035a2e','Design Consultancy Agreement Terms','PROJECT','<ol><li>Design fee payable in stages: 10% token, 30% on concept approval, 30% on GFC drawings, 30% during execution.</li><li>Two rounds of revisions included per design stage.</li><li>Site visits: weekly during execution.</li></ol>',1,0,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('1a4acd77-5dae-590a-853b-3d39b3a7e51d','Plan of Action Terms','PLAN_OF_ACTION','<ol><li>Timelines assume timely approvals (within 5 working days) and payments as per schedule.</li><li>Society/RWA restrictions on working hours may extend durations.</li><li>Monsoon (Jul-Aug) may affect civil and external works.</li></ol>',1,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('7b51c4ef-1984-5a2e-a83e-a900c3d0b67a','Budget Estimate Terms','ESTIMATE','<ol><li>This is a budgetary estimate prepared at concept stage; variance of +/-10% expected.</li><li>Design fee and PMC fee shown separately.</li><li>Final BOQ will be issued after GFC drawings.</li></ol>',1,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('9ac836d7-a2a4-500b-98bf-dc2c619c4c65','Standard Terms & Conditions','GLOBAL','<ol><li>All rates are exclusive of GST @18% unless mentioned.</li><li>Quotation valid for 30 days from date of issue.</li><li>Any work beyond approved scope will be treated as an extra item and billed at agreed rates.</li><li>Client to provide water and electricity at site free of cost.</li><li>Disputes subject to Delhi jurisdiction only.</li></ol>',2,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL),
('e2ec5efa-3bee-54fd-93ba-6e8eaf3cfd9f','BOQ Terms - Turnkey Interiors','BOQ','<ol><li>Quantities are indicative and will be measured at site on completion.</li><li>Brands as per approved material schedule; equivalent alternatives only with written approval.</li><li>Loose furniture, soft furnishings and appliances excluded unless listed.</li><li>Miscellaneous provision @10% covers minor consumables and site contingencies.</li></ol>',2,1,1,'c4af5469-bbd1-11f1-9c80-02fc00000001','036e2ab6-9740-55ad-a0f6-946d6414c1ec','2026-04-03 10:00:00','2026-08-21 10:00:00',NULL);
